    if m: return "BLOCKED:"+m.group(1)
    return "ALLOWED"
for ch in chars:
    r = test(ch)
    if r.startswith("BLOCKED"): blocked.append((ch, r))
    else: allowed.append(ch)
print("BLOCKED:", [(repr(c),r) for c,r in blocked])
print("ALLOWED:", ''.join(allowed))
